n  // Tax\n  taxIdCollected   Boolean @default(false)\n  form1099Required Boolean @default(false)\n\n  archivedAt DateTime? // Soft delete\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  expenses      ExpenseRequest[]\n  subscriptions Subscription[]\n  virtualCards  VirtualCard[]\n\n  @@index([organizationId])\n  @@index([organizationId, status]) // Vendor approval workflow queries\n}\n\nenum VendorType {\n  SAAS_SUBSCRIPTION\n  SERVICE_PROVIDER\n  ONE_TIME_VENDOR\n}\n\nenum VendorStatus {\n  DRAFT\n  PENDING\n  APPROVED\n  AWAITING_PAYMENT_SETUP\n  ACTIVE\n  BLOCKED\n  ARCHIVED\n}\n\nmodel Subscription {\n  id             String       @id @default(cuid())\n  organizationId String\n  organization   Organization @relation(fields: [organizationId], references: [id])\n  vendorId       String\n  vendor         Vendor       @relation(fields: [vendorId], references: [id])\n  grantId        String\n  categoryId     String\n\n  serviceName  String // e.g., \"Adobe Creative Cloud\"\n  loginEmail   String // Email used for the subscription account\n  monthlyCost  Decimal   @db.Decimal(10, 2)\n  billingCycle String // \"monthly\", \"annual\"\n  renewalDate  DateTime?\n\n  // Card assignment\n  cardId String?\n  card   VirtualCard? @relation(fields: [cardId], references: [id])\n\n  // Billing update tracking\n  billingUpdateStatus BillingUpdateStatus @default(PENDING)\n  billingUpdatedAt    DateTime?\n\n  status    SubscriptionStatus @default(ACTIVE)\n  createdAt DateTime           @default(now())\n  updatedAt DateTime           @updatedAt\n\n  @@index([vendorId])\n  @@index([grantId])\n  @@index([organizationId])\n  @@index([grantId, status]) // Subscription queries by grant and status\n  @@index([vendorId, status]) // Subscription queries by vendor and status\n}\n\nenum BillingUpdateStatus {\n  PENDING\n  CARD_ISSUED\n  CARD_SHARED\n  UPDATED\n  VERIFIED\n}\n\nenum SubscriptionStatus {\n  ACTIVE\n  PAUSED\n  CANCELLED\n  EXPIRED\n}\n\nmodel VirtualCard {\n  id             String          @id @default(cuid())\n  organizationId String\n  organization   Organization    @relation(fields: [organizationId], references: [id])\n  categoryId     String?\n  category       BudgetCategory? @relation(fields: [categoryId], references: [id])\n  grantId        String? // Grant this card was issued from (direct or via expense)\n  grant          Grant?          @relation(fields: [grantId], references: [id])\n  expenseId      String? // Expense this card was issued for\n  expense        ExpenseRequest? @relation(fields: [expenseId], references: [id])\n  vendorId       String? // Vendor this card is locked to\n  vendor         Vendor?         @relation(fields: [vendorId], references: [id])\n  beneficiaryId  String? // Beneficiary who uses this card\n  beneficiary    User?           @relation(\"CardBeneficiary\", fields: [beneficiaryId], references: [id])\n\n  stripeCardId    String   @unique // Stripe Issuing card ID\n  last4           String\n  expirationMonth Int\n  expirationYear  Int\n  spendingCap     Decimal? @db.Decimal(10, 2)\n  merchantLock    String? // Locked to specific merchant if applicable\n  cardType        String   @default(\"one_time\") // one_time, monthly, custom\n  cardLabel       String? // \"Writing Supplies Card\", \"Medical Copay Card\"\n\n  status    CardStatus @default(ACTIVE)\n  expiresAt DateTime? // Custom expiration\n  createdAt DateTime   @default(now())\n  updatedAt DateTime   @updatedAt\n\n  subscriptions Subscription[]\n  transactions  Transaction[]\n\n  @@index([organizationId])\n  @@index([grantId])\n  @@index([expenseId])\n  @@index([vendorId])\n  @@index([beneficiaryId])\n  @@index([stripeCardId])\n  @@index([organizationId, status]) // Card listing filtered by org and status\n}\n\nenum CardStatus {\n  ACTIVE\n  FROZEN\n  CANCELLED\n  EXPIRED\n}\n\nenum EligibilityStatus {\n  ELIGIBLE\n  RESTRICTED_CALFRESH_ONLY\n  INELIGIBLE_WARRANT\n  INELIGIBLE_INCARCERATED\n  PENDING_VERIFICATION\n}\n\nmodel CardholderEligibility {\n  id             String       @id @default(cuid())\n  beneficiaryId  String       @unique\n  beneficiary    User         @relation(fields: [beneficiaryId], references: [id])\n  organizationId String\n  organization   Organization @relation(fields: [organizationId], references: [id])\n\n  hasActiveWarrant             Boolean @default(false)\n  isCurrentlyIncarcerated      Boolean @default(false)\n  hasDrugTraffickingConviction Boolean @default(false)\n  probationParoleRestrictions  String?\n\n  eligibilityStatus EligibilityStatus @default(PENDING_VERIFICATION)\n\n  // OFAC sanctions screening\n  ofacScreened   Boolean   @default(false)\n  ofacMatchFound Boolean   @default(false)\n  ofacScreenedAt DateTime?\n  ofacMatches    Json? // Array of match results\n\n  verifiedBy String?\n  verifiedAt DateTime?\n  createdAt  DateTime  @default(now())\n  updatedAt  DateTime  @updatedAt\n\n  @@index([organizationId])\n  @@index([beneficiaryId])\n}\n\nmodel Transaction {\n  id                  String      @id @default(cuid())\n  organizationId      String\n  cardId              String\n  card                VirtualCard @relation(fields: [cardId], references: [id])\n  stripeTransactionId String      @unique\n\n  amount           Decimal @db.Decimal(10, 2)\n  merchantName     String\n  merchantCategory String?\n  status           String // \"pending\", \"completed\", \"declined\"\n  declinedReason   String?\n  grantId          String? // For ledger tracking\n  expenseId        String? // For expense tracking\n\n  createdAt DateTime @default(now())\n\n  @@index([cardId])\n  @@index([organizationId])\n  @@index([cardId, createdAt]) // Transaction history by card\n  @@index([organizationId, createdAt]) // Transaction history time-series queries\n}\n\n// ============================================\n// IMMUTABLE RECORDS — NEVER UPDATE OR DELETE\n// ============================================\n\nmodel LedgerEntry {\n  id             String          @id @default(cuid())\n  organizationId String // Denormalized from Grant for partition-aware queries\n  grantId        String\n  categoryId     String?\n  expenseId      String?\n  expense        ExpenseRequest? @relation(fields: [expenseId], references: [id])\n\n  type         LedgerType\n  amount       Decimal    @db.Decimal(12, 2)\n  balanceAfter Decimal    @db.Decimal(12, 2)\n  description  String\n  reference    String? // Transaction ID, invoice number, etc.\n\n  createdAt DateTime @default(now())\n  // IMMUTABLE — no updatedAt. Ledger entries are NEVER modified.\n\n  @@index([organizationId])\n  @@index([organizationId, createdAt])\n  @@index([grantId])\n  @@index([expenseId])\n  @@index([grantId, createdAt]) // Monthly reconciliation queries at scale\n}\n\nenum LedgerType {\n  CREDIT\n  DEBIT\n}\n\nmodel Approval {\n  id             String         @id @default(cuid())\n  organizationId String\n  organization   Organization   @relation(fields: [organizationId], references: [id])\n  expenseId      String\n  expense        ExpenseRequest @relation(fields: [expenseId], references: [id])\n  approverId     String\n  approver       User           @relation(fields: [approverId], references: [id])\n  action         ApprovalAction\n  notes          String?\n  createdAt      DateTime       @default(now())\n\n  @@index([expenseId])\n  @@index([organizationId])\n}\n\nenum ApprovalAction {\n  APPROVED\n  REJECTED\n  REQUESTED_INFO\n}\n\nmodel AuditLog {\n  id             String   @id @default(cuid())\n  userId         String\n  organizationId String\n  action         String // \"create\", \"update\", \"delete\", \"approve\", \"reject\"\n  entityType     String // \"grant\", \"expense\", \"vendor\", \"card\", etc.\n  entityId       String\n  oldValue       Json?\n  newValue       Json?\n  ipAddress      String?\n  userAgent      String?\n  createdAt      DateTime @default(now())\n  // IMMUTABLE — no updatedAt. Audit logs are NEVER modified or deleted.\n\n  @@index([organizationId])\n  @@index([entityType, entityId])\n  @@index([userId, organizationId]) // Audit queries by user within an org\n  @@index([organizationId, createdAt]) // Audit trail time-series queries\n}\n\n// ============================================\n// MESSAGING\n// ============================================\n\nmodel Conversation {\n  id             String   @id @default(cuid())\n  organizationId String\n  subject        String?\n  type           String   @default(\"direct\") // direct, department, support\n  department     String? // \"grants\", \"compliance\", \"support\", etc.\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  participants ConversationParticipant[]\n  messages     Message[]\n\n  @@index([organizationId])\n}\n\nmodel ConversationParticipant {\n  id             String       @id @default(cuid())\n  conversationId String\n  conversation   Conversation @relation(fields: [conversationId], references: [id])\n  userId         String\n  role           String       @default(\"member\") // member, admin\n  lastReadAt     DateTime     @default(now())\n  createdAt      DateTime     @default(now())\n\n  @@unique([conversationId, userId])\n  @@index([userId])\n}\n\nmodel Message {\n  id             String       @id @default(cuid())\n  conversationId String\n  conversation   Conversation @relation(fields: [conversationId], references: [id])\n  senderId       String\n  content        String\n  attachmentUrl  String?\n  attachmentName String?\n  createdAt      DateTime     @default(now())\n\n  @@index([conversationId, createdAt])\n  @@index([senderId])\n}\n\nmodel Notification {\n  id             String   @id @default(cuid())\n  userId         String // Who receives this notification\n  organizationId String\n  type           String // expense_submitted, expense_approved, expense_rejected, vendor_profile_complete, invite_accepted, card_issued\n  title          String\n  message        String\n  entityType     String? // grant, expense, vendor, user\n  entityId       String?\n  href           String? // Link to navigate to\n  read           Boolean  @default(false)\n  createdAt      DateTime @default(now())\n\n  @@index([userId, read])\n  @@index([organizationId, createdAt]) // Notification queries by org and date\n}\n\n// ============================================\n// SUPPORTING MODELS\n// ============================================\n\nmodel Document {\n  id             String   @id @default(cuid())\n  organizationId String\n  entityType     String // \"expense\", \"vendor\", \"grant\"\n  entityId       String\n  fileName       String\n  fileUrl        String // S3 URL\n  fileType       String // \"receipt\", \"invoice\", \"contract\", \"grant_letter\"\n  uploadedById   String\n  createdAt      DateTime @default(now())\n\n  @@index([organizationId])\n  @@index([entityType, entityId])\n}\n\nmodel DisbursementPolicy {\n  id             String       @id @default(cuid())\n  organizationId String\n  organization   Organization @relation(fields: [organizationId], references: [id])\n  grantId        String? // If null, applies to all grants for this org\n\n  cashToRecipient          PolicySetting @default(DISALLOWED)\n  reimbursementToRecipient PolicySetting @default(DISALLOWED)\n  rentUtilityPayments      PolicySetting @default(REQUIRES_REVIEW)\n  recurringSubscriptions   PolicySetting @default(ALLOWED)\n  maxSingleTransaction     Decimal?      @db.Decimal(10, 2)\n\n  // Auto-approval settings for card charges\n  autoApproveEnabled    Boolean  @default(false)\n  autoApproveMaxAmount  Decimal? @db.Decimal(12, 2)\n  autoApproveCategories Json? // Array of category IDs eligible for auto-approval\n  autoApproveRiskLevels Json? // e.g. [\"LIKELY_SAFE\"] — default checked in code\n  requireReviewAbove    Decimal? @db.Decimal(12, 2)\n\n  allowedCategories Json? // Array of allowed expense category names\n  blockedCategories Json? // Array of blocked expense category names\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([organizationId])\n}\n\nenum PolicySetting {\n  ALLOWED\n  DISALLOWED\n  REQUIRES_REVIEW\n}\n\n// ============================================\n// PROMO CODES & FREE TRIALS\n// ============================================\n\nmodel PromoCode {\n  id          String    @id @default(cuid())\n  code        String    @unique\n  description String?\n  trialDays   Int // How many days of free access this code gives\n  maxUses     Int       @default(50) // Max number of times this code can be used\n  currentUses Int       @default(0)\n  isActive    Boolean   @default(true)\n  expiresAt   DateTime? // When the code itself expires\n  createdById String // platform_admin who created it\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  redemptions PromoRedemption[]\n\n  @@index([code])\n  @@index([isActive])\n}\n\nmodel PromoRedemption {\n  id             String       @id @default(cuid())\n  promoCodeId    String\n  promoCode      PromoCode    @relation(fields: [promoCodeId], references: [id])\n  organizationId String\n  organization   Organization @relation(fields: [organizationId], references: [id])\n  redeemedById   String // User who redeemed it\n  redeemedAt     DateTime     @default(now())\n\n  @@unique([promoCodeId, organizationId]) // One code per org\n  @@index([organizationId])\n}\n\n// ============================================\n// CALENDAR EVENTS\n// ============================================\n\nmodel CalendarEvent {\n  id             String       @id @default(cuid())\n  organizationId String\n  organization   Organization @relation(fields: [organizationId], references: [id])\n  title          String\n  description    String?\n  startDate      DateTime\n  endDate        DateTime?\n  category       String       @default(\"general\") // grants, payments, compliance, subscriptions, general\n  color          String? // hex color for calendar display\n  createdById    String\n  createdAt      DateTime     @default(now())\n  updatedAt      DateTime     @updatedAt\n\n  @@index([organizationId])\n  @@index([startDate])\n}\n\n// ============================================\n// MULTI-TENANT MEMBERSHIPS\n// ============================================\n\nmodel OrganizationMembership {\n  id               String    @id @default(cuid())\n  userId           String\n  organizationId   String\n  role             String    @default(\"member\") // matches UserRole values: nonprofit_admin, beneficiary, vendor, cpa, auditor, attorney, platform_admin, member, etc.\n  memberCode       String?   @unique // e.g., \"TM-0001-00001\" (orgSeq-memberSeq)\n  status           String    @default(\"active\") // active, suspended, pending, revoked\n  invitedBy        String?\n  joinedAt         DateTime  @default(now())\n  isDefaultOrg     Boolean   @default(false)\n  lastAccessedAt   DateTime?\n  orgSpecificTitle String?\n  createdAt        DateTime  @default(now())\n  updatedAt        DateTime  @updatedAt\n\n  user         User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  organization Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n\n  // Per-org private notes about this member. Lets nonprofit A keep a\n  // case file on Maria without leaking those notes to nonprofit B that\n  // also has Maria as a beneficiary. The legacy User.notes field is\n  // retained for backward compat but new writes go here.\n  notes String?\n\n  @@unique([userId, organizationId])\n  @@index([userId])\n  @@index([organizationId])\n  @@index([userId, status])\n  // Hot path for multi-org list endpoints: filters by\n  // (organizationId, role, status) on every beneficiary/team list call.\n  // Keeps the query an indexed range read at 900M+ rows.\n  @@index([organizationId, role, status])\n}\n\nmodel CronCheckpoint {\n  // Resumable cursor checkpoint for dispatcher crons. Each row is keyed\n  // by a stable cronName (\"compliance-dispatcher\", \"sentinel-dispatcher\",\n  // etc.) and stores the last-processed entity id so the next cron tick\n  // picks up where the previous one stopped, instead of re-scanning the\n  // table from the beginning.\n  id             String   @id @default(cuid())\n  cronName       String   @unique\n  lastCursor     String?\n  lastRunAt      DateTime @default(now())\n  processedCount Int      @default(0)\n  updatedAt      DateTime @updatedAt\n\n  @@index([cronName])\n}\n\n// ── Composio Workflow Automation ────────────────────\n\nmodel Integration {\n  id                   String       @id @default(cuid())\n  organizationId       String\n  organization         Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  provider             String // \"gmail\", \"slack\", \"google_calendar\", \"google_sheets\", \"asana\", \"trello\"\n  composioConnectionId String? // Composio's connection ID for this org+provider\n  status               String       @default(\"disconnected\") // \"connected\", \"disconnected\", \"error\"\n  connectedBy          String? // userId of who connected it\n  connectedAt          DateTime?\n  createdAt            DateTime     @default(now())\n  updatedAt            DateTime     @updatedAt\n\n  @@unique([organizationId, provider])\n  @@index([organizationId])\n}\n\nmodel WorkflowTrigger {\n  id             String       @id @default(cuid())\n  organizationId String\n  organization   Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  eventType      String // \"expense_approved\", \"card_issued\", \"transaction_needs_review\", \"grant_low_balance\", \"beneficiary_onboarded\"\n  provider       String // which integration this trigger uses\n  actionSlug     String // Composio tool slug, e.g. \"GMAIL_SEND_EMAIL\"\n  actionConfig   Json // template data: subject, body template, channel, etc.\n  enabled        Boolean      @default(true)\n  createdAt      DateTime     @default(now())\n  updatedAt      DateTime     @updatedAt\n\n  @@index([organizationId, eventType])\n  @@index([organizationId, enabled])\n}\n\nmodel WorkflowLog {\n  id              String       @id @default(cuid())\n  organizationId  String\n  organization    Organization @relation(fields: [organizationId], references: [id], onDelete: Cascade)\n  triggerId       String\n  eventType       String\n  provider        String\n  actionSlug      String\n  status          String // \"success\", \"failed\", \"skipped\"\n  requestPayload  Json?\n  responsePayload Json?\n  errorMessage    String?\n  executionTimeMs Int?\n  createdAt       DateTime     @default(now())\n\n  @@index([organizationId, createdAt])\n  @@index([triggerId])\n}\n\n// ── Grant Reports (generated by SentinelLayer Reporter) ──────\n\nmodel GrantReport {\n  id             String   @id @default(cuid())\n  organizationId String\n  grantId        String\n  reportType     String   @default(\"weekly_disbursement\")\n  reportData     Json\n  periodStart    DateTime\n  periodEnd      DateTime\n  generatedAt    DateTime @default(now())\n  generatedBy    String   @default(\"sentinellayer_reporter\")\n  status         String   @default(\"draft\") // draft, reviewed, final\n\n  @@index([organizationId, grantId])\n  @@index([organizationId, generatedAt])\n}\n\n// ============================================\n// BILLING & USAGE (BenefitsSafe platform billing)\n// Separate from `model Subscription` which tracks vendor SaaS\n// subscriptions paid on behalf of beneficiaries.\n// ============================================\n\nmodel BillingSubscription {\n  id             String       @id @default(cuid())\n  organizationId String       @unique\n  organization   Organization @relation(fields: [organizationId], references: [id])\n\n  tier                 String  @default(\"free\") // free, starter, growth, professional, enterprise\n  stripeCustomerId     String?\n  stripeSubscriptionId String?\n  stripePriceId        String?\n\n  currentPeriodStart DateTime?\n  currentPeriodEnd   DateTime?\n  cancelAtPeriodEnd  Boolean   @default(false)\n\n  status String @default(\"trialing\") // trialing, active, past_due, canceled, unpaid\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([organizationId])\n  @@index([stripeCustomerId])\n  @@index([stripeSubscriptionId])\n}\n\nmodel UsageCounter {\n  id             String       @id @default(cuid())\n  organizationId String\n  organization   Organization @relation(fields: [organizationId], references: [id])\n\n  period             String // \"2026-04\" (year-month)\n  beneficiariesAdded Int    @default(0)\n  grantsCreated      Int    @default(0)\n  expensesProcessed  Int    @default(0)\n  cardsIssued        Int    @default(0)\n  apiCalls           Int    @default(0)\n  storageMB          Float  @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([organizationId, period])\n  @@index([organizationId])\n}\n",
